{
  "technical_and_design_decisions": [
    "All code changes are targeted at the Spring XD 1.1.0.BUILD-SNAPSHOT codebase, aligned with the version referenced in the ulimit error specification.",
    "The log date format added to the container logger (U3) will use ISO 8601 (yyyy-MM-dd'T'HH:mm:ss.SSSZ) to ensure consistent, sortable timestamps across all log entries.",
    "Kafka test refactoring (U4, U6) will use Testcontainers for local separate Kafka process management to avoid manual Kafka installation, and will add a dedicated test profile for external broker configuration to maintain backward compatibility with existing embedded Kafka tests.",
    "The Spark batch job sample (U8) will follow standard Spring XD module structure, use Scala as the implementation language, and include a simple word count use case to demonstrate distributed computation capabilities.",
    "The publish-maven.gradle script update (U5) will include a fallback mechanism to use existing hardcoded dependency versions if the corresponding property is missing from dependencies.properties to prevent build breakage during transition.",
    "Sonar violation triage (U7) will prioritize fixes for violations categorized as bugs, security hotspots, and critical code smells, with irrelevant violations (e.g. generated code, third-party library issues) marked as false positives."
  ],
  "assumptions": [
    "The development team has write access to the Spring XD wiki repository to update the Troubleshooting section per U2.",
    "The central dependencies.properties file referenced in U5 exists in the project root and contains valid version entries for Spring Boot and hadoop-common.",
    "The existing Kafka test suite uses an embedded Kafka broker by default, and refactoring to support separate and external brokers will not require changes to core test logic.",
    "A container registry is available for hosting the pre-built Spark Streaming module Docker image referenced in U1.",
    "The Sonar instance for the Spring XD project is already configured and accessible to the development team for triaging and updating violation statuses per U7.",
    "The Spark Streaming module referenced in U1 already exists in the Spring XD codebase and only requires containerization and deployment documentation updates to meet the user story requirement."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Create pre-built Docker image for Scala Spark Streaming module",
      "activity_description": "Create and configure a Dockerfile for the existing Scala Spark Streaming Spring XD module, test the image for compatibility with Spring XD containers, push the image to the project's container registry, and update deployment documentation to reference the pre-built image to simplify deployment for Scala developers.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Update Spring XD wiki with ulimit recommendations and error guidance",
      "activity_description": "Add a new 'Troubleshooting' section to the Spring XD wiki, document the recommended 10K ulimit setting for distributed XD deployments, and add a troubleshooting entry for the 'Too many open files' exception (referencing the 1.1.0.SNAP error) with resolution steps.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Update container logging configuration to include date in logs",
      "activity_description": "Modify the xd-container-logger.properties file (line 11 as referenced in the specification) to add an ISO 8601 formatted date timestamp to all Spring XD container log patterns, verify log output includes correctly formatted dates across all container and module components.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "Refactor Kafka tests to use separate local Kafka process",
      "activity_description": "Update existing Kafka integration tests to launch a local Kafka server as a separate OS process instead of using an embedded broker, configure test setup and teardown logic to manage the separate process lifecycle, and verify all existing Kafka tests pass with the new configuration.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Update publish-maven.gradle to use central dependency versions",
      "activity_description": "Modify the publish-maven.gradle script to read version values for Spring Boot and hadoop-common from the project's central dependencies.properties file instead of hardcoded values, add fallback logic to use existing hardcoded values if the property is missing, and verify the script functions correctly for Maven publish workflows.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "Add external Kafka broker support to Kafka test suite",
      "activity_description": "Add a dedicated test configuration profile to the Kafka test suite that allows tests to connect to an external (non-local) Kafka broker, update test documentation to explain configuration for external broker testing, and verify tests pass when pointed to a valid external Kafka instance.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A7",
      "activity_name": "Triage and resolve Spring XD Sonar violations",
      "activity_description": "Pull the current list of Sonar violations for the Spring XD project, triage each violation to identify relevant issues (bugs, security, code smells) vs irrelevant false positives, fix all relevant violations, mark irrelevant violations as won't fix/false positive in Sonar, and verify the project Sonar quality gate passes after changes.",
      "most_likely_effort": 11
    },
    {
      "activity_id": "A8",
      "activity_name": "Develop sample Spark batch job module for Spring XD",
      "activity_description": "Create a new sample Spark batch job module following Spring XD module conventions, implement a simple distributed data computation use case (e.g. word count) using Scala, add a README with build and deployment instructions, and verify the sample runs correctly in a local Spring XD container.",
      "most_likely_effort": 9
    }
  ],
  "reported_total": {
    "most_likely_effort": 56
  }
}

